use crate::aap::caps::inference_llm;

/// `ensures len(overview) <= 600`. Measured in bytes, which bounds characters too.
const OVERVIEW_MAX: usize = 600;

const SYSTEM: &str = "You write a short overview of a feed digest. \
Summarise only the items you are given. Plain text, no markup, at most three sentences.";

struct Node;

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        let kept = selected.entries.iter().filter(|e| e.kept).count();
        let prompt = build_prompt(&selected.entries);

        let raw = inference_llm::infer(SYSTEM, &prompt, "digest");
        let mut overview = bound(raw.trim(), OVERVIEW_MAX);
        if overview.is_empty() {
            overview = bound(&format!("{kept} item(s) kept in this digest."), OVERVIEW_MAX);
        }

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

fn build_prompt(entries: &[ItemVerdict]) -> String {
    let mut out = String::from("Items:\n");
    for e in entries.iter().filter(|e| e.kept) {
        out.push_str("- ");
        out.push_str(&e.title);
        out.push_str(": ");
        out.push_str(&e.summary);
        out.push('\n');
    }
    out
}

/// Truncate to at most `max` bytes, never splitting a UTF-8 character.
fn bound(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

export!(Node);
